```json
{
 "didatica": [
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "volume do cone = 1/3 × π × r² × h",
    "volume do cilindro = π × r² × h",
    "massa = 0,6 g/cm³ × volume em cm³"
   ],
   "motivo": "Padroniza a fração, que o site desenha empilhada, e tira os parênteses e o símbolo · desnecessários."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["r", "raio da base, que é metade do diâmetro"],
    ["h", "altura do sólido"],
    ["π", "número que a questão manda usar como 3"],
    ["tronco de cone", "cone sem a ponta; sobra o pedaço de baixo, entre duas bases paralelas"],
    ["semelhantes", "mesma forma, tamanhos diferentes; todas as medidas ficam na mesma proporção"],
    ["cm³", "centímetro cúbico, unidade de volume"]
   ],
   "motivo": "A palavra 'semelhantes' e a unidade cm³ aparecem nos passos e não estavam explicadas."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "6/18 = h/36 → h = 12",
   "motivo": "Cabe na tela de celular e fica coerente com o restante do quadro."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "Os dois cones são semelhantes: todas as medidas do pequeno são a mesma fração das do grande. O diâmetro 6 é 1/3 de 18, então a altura também é 1/3 de 36, ou seja, 12 cm.",
   "motivo": "Explica a proporção em palavras simples."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "1/3 × 3 × 81 × 36 = 2916",
   "motivo": "Troca o símbolo · por ×, que o aluno usa no caderno, e mostra a conta completa."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "1/3 × 3 × 9 × 12 = 108",
   "motivo": "Mostra a conta completa, e o cone pequeno fica separado do cálculo do tronco."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "O cone do topo tem raio 3, e 3² = 9. Com altura 12, o volume é 9 × 12 = 108 cm³. Tire esse cone do grande: o tronco fica com 2916 − 108 = 2808 cm³.",
   "motivo": "A frase original, 'pesa na conta', confundia volume com peso."
  },
  {
   "campo": "resolucao.passos[4].conta",
   "depois": "h = 36 − 12 = 24 ; 3 × 9 × 24 = 648",
   "motivo": "O passo é do volume do furo, e a conta mostrava só a altura."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "O furo vai de base a base do tronco, que tem 36 − 12 = 24 cm de altura. O raio do furo é 3 cm, então V = 3 × 3² × 24 = 648 cm³.",
   "motivo": "Deixa claro de onde vem a altura 24 e usa a fórmula do cilindro."
  },
  {
   "campo": "resolucao.passos[5].faz",
   "depois": "Ache o volume final e a massa",
   "motivo": "O passo calcula o volume e depois a massa; o comando antigo só falava da massa."
  },
  {
   "campo": "resolucao.passos[5].conta",
   "depois": "2808 − 648 = 2160 ; 0,6 × 2160 = 1296",
   "motivo": "Mostra as duas contas, volume e massa, no mesmo passo."
  },
  {
   "campo": "resolucao.checagem",
   "depois": "Calcule o tronco direto pela fórmula V = 1/3 × π × h × (R² + R×r + r²). Com π = 3, h = 24, R = 9 e r = 3: 1/3 × 3 × 24 × (81 + 27 + 9) = 24 × 117 = 2808. Confere com 2916 − 108. Menos o furo de 648, dá 2160.",
   "motivo": "Troca a fração e o símbolo · pela escrita padrão do caderno."
  },
  {
   "campo": "resolucao.erradas.A",
   "depois": "1198,8 não confere: 1198,8 ÷ 0,6 = 1998 cm³, e nenhuma etapa (2916, 108, 2808, 648) leva a 1998. O volume correto da escultura é 2160 cm³.",
   "motivo": "Deixa claro o teste que derruba a alternativa, no padrão 'não confere'."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "1360,8 sai de 0,6 × 2268, e 2268 = 2916 − 648. Esqueceu de retirar o cone pequeno do topo (108 cm³): não notou que a escultura é um tronco, e não o cone inteiro.",
   "motivo": "Diz o que faltou no raciocínio de quem marcou a letra."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "4665,6 sai de 0,6 × 7776, e 7776 = 8748 − 324 − 648. Usou π × r² × h nos cones, sem o fator 1/3: o cone grande deu 8748 em vez de 2916. Cone leva sempre 1/3.",
   "motivo": "Explica o que faltou: o 1/3 do cone."
  },
  {
   "campo": "resolucao.erradas.E",
   "depois": "4860 sai de 0,6 × 8100, e 8100 = 8748 − 648. Faltou o 1/3 no cone grande e também retirar o cone pequeno do topo.",
   "motivo": "Texto mais direto."
  },
  {
   "campo": "resolucao.caminhos[0].ideia",
   "depois": "Com altura 24 e raios 9 e 3: V = 1/3 × π × 24 × (81 + 27 + 9) = 1/3 × 3 × 24 × 117 = 24 × 117 = 2808 cm³. Depois subtraia o cilindro de 648 cm³.",
   "motivo": "Fração padronizada."
  },
  {
   "campo": "resolucao.quadro",
   "depois": [
    {"linha": "Cone grande: r = 9, h = 36", "nota": "diâmetro 18 → raio 9"},
    {"linha": "6/18 = h/36", "nota": "cones semelhantes"},
    {"linha": "h = 12", "nota": "altura do cone pequeno"},
    {"linha": "V1 = 1/3 × 3 × 9² × 36", "nota": "cone grande, π = 3"},
    {"linha": "V1 = 81 × 36 = 2916", "nota": "o 1/3 cancela o 3"},
    {"linha": "V2 = 1/3 × 3 × 3² × 12", "nota": "cone pequeno, r = 3"},
    {"linha": "V2 = 9 × 12 = 108", "nota": "volume do cone pequeno"},
    {"linha": "Tronco = 2916 − 108", "nota": "tira o cone do topo"},
    {"linha": "Tronco = 2808", "nota": "em cm³"},
    {"linha": "Furo: h = 36 − 12 = 24", "nota": "de base a base do tronco"},
    {"linha": "V3 = 3 × 3² × 24", "nota": "cilindro de raio 3, π = 3"},
    {"linha": "V3 = 3 × 9 × 24 = 648", "nota": "em cm³"},
    {"linha": "V = 2808 − 648 = 2160", "nota": "volume da escultura"},
    {"linha": "m = 0,6 × 2160", "nota": "massa por cm³ vezes volume"},
    {"linha": "m = 1296,0 g", "nota": "alternativa B"}
   ],
   "motivo": "Troca o símbolo · por ×, padroniza as frações e separa em duas linhas a conta do cilindro, que não passava de uma linha."
  }
 ],
 "didatica_alertas": [],
 "didatica_ok": true
}
